package br.com.archlab.simulation.core.v3;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static br.com.archlab.simulation.core.v3.ArchitectureV3.*;import static br.com.archlab.simulation.core.v3.SynchronousExecutionV3Test.*;
class ScenarioValidatorV3Test {
    private final ScenarioValidatorV3 validator=new ScenarioValidatorV3();
    SimulationRequestV3 request(){return AsynchronousExecutionV3Test.reference(ExecutionPlanV3.AwaitPublish.NONE,Map.of());}
    SimulationRequestV3 resource(SimulationRequestV3 r,String name,Map<String,PropertyValueV3> values){var a=r.architecture();var resources=a.resources().stream().map(x->x.id().value().equals(name)?new Resource(x.id(),x.typeId(),x.ownerId(),values):x).toList();return new SimulationRequestV3(new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),resources,a.endpoints(),a.operations(),a.relations(),a.executionPlans()),r.scenario(),r.options());}
    @Test void admitsSixComponentReferenceWithoutChangingTheInput(){var r=request();String hash=InputFingerprintV3.hash(r);assertTrue(validator.validate(r).valid());assertEquals(hash,InputFingerprintV3.hash(r));}
    @Test void rejectsQueueWithoutConsumerAndInvalidTopicRouting(){var r=request();assertFalse(validator.validate(resource(r,"messages",Map.of("capacity",n(1)))).valid());assertFalse(validator.validate(resource(r,"topic",Map.of("queueIds",new PropertyValueV3.Values(List.of())))).valid());assertFalse(validator.validate(resource(r,"topic",Map.of("queueIds",new PropertyValueV3.Values(List.of(new PropertyValueV3.Reference(id("db-pool"),id("PROCESSING_POOL"))))))).valid());}
    @Test void rejectsNativePolicyUnknownStateAndOversizedSeedQueue(){var r=SynchronousExecutionV3Test.fixture(null,10L,false,true);var s=r.scenario();var changed=new SimulationRequestV3.Scenario(s.id(),s.entry(),List.of(new InitialStateV3.Policy(id("call-policy"),"OPEN")),Map.of());assertTrue(validator.validate(new SimulationRequestV3(r.architecture(),changed,r.options())).violations().stream().anyMatch(v->v.code().equals("POLICY_STATE_NOT_SUPPORTED")));}
    @Test void rejectsConnectionMismatchAndMissingEntryBeforeExecution(){var r=request();var s=r.scenario();var e=new SimulationRequestV3.Entry(id("client"),id("api-op"),id("api-db"),null);var changed=new SimulationRequestV3.Scenario(s.id(),e,s.initialStates(),s.parameters());assertTrue(validator.validate(new SimulationRequestV3(r.architecture(),changed,r.options())).violations().stream().anyMatch(v->v.code().equals("ENTRY_CONNECTION_MISMATCH")));}
    @Test void rejectsUnsupportedNumericRangesAndZeroDeliveryConcurrency(){var r=request();var old=r.architecture().resources().stream().filter(x->x.id().value().equals("messages")).findFirst().orElseThrow();var props=new HashMap<>(old.properties());props.put("consumerConcurrency",n(0));assertFalse(validator.validate(resource(r,"messages",props)).valid());props.put("consumerConcurrency",n(1));props.put("ackTimeoutMs",n(Long.MAX_VALUE));assertFalse(validator.validate(resource(r,"messages",props)).valid());assertFalse(validator.validate(new SimulationRequestV3(r.architecture(),r.scenario(),new SimulationRequestV3.Options(7,SimulationRequestV3.CompletionMode.UNTIL_HORIZON,Long.MAX_VALUE))).valid());}
}
